'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var detect = require( './../lib' );


// VARIABLES //

var hasPromise = ( typeof Promise === 'function' ); // eslint-disable-line stdlib/require-globals


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof detect, 'function', 'main export is a function' );
	t.end();
});

tape( 'feature detection result is a boolean', function test( t ) {
	t.strictEqual( typeof detect(), 'boolean', 'detection result is a boolean' );
	t.end();
});

tape( 'if `Promise` is supported, detection result is `true`', function test( t ) {
	var mocked;
	var Mock;

	if ( hasPromise ) {
		t.strictEqual( detect(), true, 'detection result is `true`' );
	} else {
		t.strictEqual( detect(), false, 'detection result is `false`' );
	}

	Mock = createMock({
		'resolve': true,
		'reject': true
	});
	mocked = proxyquire( './../lib/main.js', {
		'./promise.js': Mock
	});
	t.strictEqual( mocked(), true, 'detection result is `true` (mocked)' );
	t.end();
});

tape( 'if `Promise` is not supported, detection result is `false`', function test( t ) {
	var mocked;
	var Mock;

	if ( hasPromise ) {
		t.strictEqual( detect(), true, 'detection result is `true`' );
	} else {
		t.strictEqual( detect(), false, 'detection result is `false`' );
	}
	mocked = proxyquire( './../lib/main.js', {
		'./promise.js': {}
	});
	t.strictEqual( mocked(), false, 'detection result is `false` (mocked)' );

	Mock = createMock({
		'reject': true
	});
	mocked = proxyquire( './../lib/main.js', {
		'./promise.js': Mock
	});
	t.strictEqual( mocked(), false, 'detection result is `false` (no `resolve` method)' );

	Mock = createMock({
		'resolve': true
	});
	mocked = proxyquire( './../lib/main.js', {
		'./promise.js': Mock
	});
	t.strictEqual( mocked(), false, 'detection result is `false` (no `reject` method)' );

	t.end();
});


// FUNCTIONS //

/**
* Returns a mock Promise constructor.
*
* @private
* @param {Object} methods - methods to attach
* @param {boolean} [methods.resolve] - boolean indicating whether to attach a `resolve` method
* @param {boolean} [methods.reject] - boolean indicating whether to attach a `reject` method
* @returns {Function} mock constructor
*/
function createMock( methods ) {
	function Mock() {
		// No-op...
	}
	if ( methods.resolve ) {
		Mock.resolve = noop;
	}
	if ( methods.reject ) {
		Mock.reject = noop;
	}
	Mock[ '@noCallThru' ] = true;
	return Mock;

	/**
	* No-op function.
	*
	* @private
	*/
	function noop() {
		// No-op...
	}
}
